// Simple Node.js round-robin proxy (http-proxy)
const http = require('http');
const httpProxy = require('http-proxy');
const targets = ['http://localhost:3001','http://localhost:3002','http://localhost:3003'];
let idx = 0;
const proxy = httpProxy.createProxyServer();
const server = http.createServer((req,res)=>{
  const target = targets[idx % targets.length];
  idx += 1;
  proxy.web(req,res,{ target }, err => {
    res.writeHead(502); res.end('Bad gateway');
  });
});
server.listen(8000, ()=> console.log('LB listening on 8000'));
